1	// Acceptance test for the change request:
2	//   "Give me a statement for a client. Put all their invoices in one place. Show the total they
3	//    still owe me."
4	//
5	// A client now has a STATEMENT, surfaced on that client's own detail page (client-detail-page, the
6	// child route /clients/<id>). A control opens it (client-statement-open), revealing the statement
7	// region (client-statement). The statement puts ALL of that client's invoices IN ONE PLACE — every
8	// invoice across every project the client owns — in one table (client-statement-table). Each invoice
9	// is its own row (statement-invoice-row-<id>) carrying:
10	//   - statement-invoice-id      — which invoice it is
11	//   - statement-invoice-amount  — the invoice's amount
12	//   - statement-invoice-paid    — how much has been paid against it (the sum of its payments)
13	//   - statement-invoice-due     — how much is STILL LEFT TO PAY on it (amount minus what is paid)
14	//   - statement-invoice-status  — its worked-out state: owing / part paid / paid
15	// And the statement shows the TOTAL the client still owes (client-outstanding-total): the sum, across
16	// all the client's invoices, of what is still left to pay on each.
17	//
18	// WHY THESE VALUES. The app already works out, per invoice, how much is still left to pay after
19	// payments (invoice-due-amount.spec: amount minus the sum of payments) and a status from those
20	// payments (invoice-paid.spec: still owing -> part paid -> paid). The statement is the per-client
21	// roll-up of exactly that: each row is one invoice's amount/paid/due/status, and the total owed is
22	// the sum of the per-invoice dues. A fully-paid invoice is still LISTED (it is one of their invoices)
23	// but owes nothing, so it adds 0 to the total. All invoices below are SENT, so "what is owed" is
24	// unambiguous — the question of unsent drafts does not arise here.
25	//
26	// The seeded figures are chosen so the right total can only come from summing the per-invoice dues:
27	// amount 500 with 200 paid (due 300), amount 400 fully paid (due 0), amount 150 with nothing paid
28	// (due 150) => owed 300 + 0 + 150 = 450. That 450 is none of the plausible wrong readings — not the
29	// gross of every amount (1050), not the gross of the not-fully-paid ones (650), and not anything that
30	// includes the OTHER client's invoice.
31	//
32	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
33	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId },
34	// `invoices` honours { id, amount, projectId, status } and `payments` honours
35	// { id, invoiceId, amount, date }. This change surfaces no audit records, so there is nothing to
36	// assert on the audit channel.
37	import { test, expect, type Page, type Locator } from '@playwright/test';
38	import { resetAndSeed } from '../support/seed';
39	
40	const statementRows = (page: Page) =>
41	  page.locator('[data-testid^="statement-invoice-row-"]');
42	
43	const cell = (page: Page, id: number, name: string): Locator =>
44	  page.getByTestId(`statement-invoice-row-${id}`).getByTestId(name);
45	
46	const paymentRows = (page: Page) => page.locator('[data-testid^="payment-row-"]');
47	const rowByAmount = (page: Page, amount: number): Locator =>
48	  paymentRows(page).filter({ has: page.getByTestId('payment-amount').getByText(String(amount)) });
49	
50	// Money is shown "properly" everywhere in this app — a dollar sign and two cents digits, e.g.
51	// $265.00 (money-format.spec). So each money figure (amount, paid, due, outstanding total) is
52	// asserted as CONTAINMENT of that value: the leading "$" keeps a figure from matching inside a larger
53	// number ($300.00 cannot match within $1300.00) and tolerates a surrounding label, while still
54	// pinning the value. Every figure below stays under a thousand, so thousands grouping never arises.
55	const money = (dollars: number): RegExp => new RegExp(`\\$${dollars}\\.00`);
56	
57	// An invoice's id, matched as a standalone number token so a decoration like "#1" or "Invoice 1" is
58	// tolerated while the digits are still pinned. The id cell carries only the id, so this is read on
59	// that cell alone.
60	const idToken = (id: number): RegExp => new RegExp(`(^|\\D)${id}(\\D|$)`);
61	
62	// The worked-out status words, matched case-insensitively so the test binds to MEANING not phrasing
63	// ("Owing"/"Still owing", "Part paid"/"Partly paid", "Paid"/"Paid in full"). "paid" is a substring of
64	// "part paid", so FULLY paid is "paid" WITHOUT "part"; a word boundary keeps it off "unpaid" too.
65	// Mirrors invoice-paid.spec, whose status this statement rolls up.
66	const OWING = /owing/i;
67	const PART = /part/i;
68	const PAID = /\bpaid\b/i;
69	
70	type Status = 'owing' | 'part' | 'paid';
71	
72	async function expectRowStatus(page: Page, id: number, status: Status): Promise<void> {
73	  const status_cell = cell(page, id, 'statement-invoice-status');
74	  await expect(status_cell).toBeVisible();
75	  if (status === 'owing') {
76	    await expect(status_cell).toHaveText(OWING);
77	    await expect(status_cell).not.toHaveText(PAID); // nothing paid: not paid, not part paid
78	  } else if (status === 'part') {
79	    await expect(status_cell).toHaveText(PART);
80	    await expect(status_cell).not.toHaveText(OWING); // some paid: no longer merely owing
81	  } else {
82	    await expect(status_cell).toHaveText(PAID);
83	    await expect(status_cell).not.toHaveText(PART); // fully paid, not part paid
84	    await expect(status_cell).not.toHaveText(OWING);
85	  }
86	}
87	
88	// Reach a client's statement the way a user would: open the client's detail page, then open the
89	// statement with its own control. The statement is a reveal on the detail page (a show/hide the
90	// control owns), not a separate URL, so the contract is "the open control makes the statement appear".
91	async function openStatement(page: Page, clientId: number): Promise<void> {
92	  await page.goto(`/clients/${clientId}`);
93	  await expect(page.getByTestId('client-detail-page')).toBeVisible();
94	  const opener = page.getByTestId('client-statement-open');
95	  await expect(opener).toBeVisible();
96	  await opener.click();
97	  await expect(page.getByTestId('client-statement')).toBeVisible();
98	  await expect(page.getByTestId('client-statement-table')).toBeVisible();
99	}
100	
101	// A client (Acme) with TWO projects and invoices spread across BOTH, plus a SECOND client (Globex)
102	// whose invoice must never leak into Acme's statement. Acme's three invoices carry distinct
103	// amount/paid/due triples so each row pins its own figures and the owed total can only be their sum.
104	async function seedTwoClients(): Promise<void> {
105	  await resetAndSeed({
106	    clients: [
107	      { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
108	      { id: 2, name: 'Globex', email: 'contact@globex.test' },
109	    ],
110	    projects: [
111	      { id: 1, name: 'Website Redesign', clientId: 1 },
112	      { id: 2, name: 'Mobile App', clientId: 1 },
113	      // Globex's own project — its invoice belongs to Globex, not Acme.
114	      { id: 3, name: 'Billing System', clientId: 2 },
115	    ],
116	    invoices: [
117	      { id: 1, amount: 500, projectId: 1, status: 'SENT' }, // 200 paid -> due 300, part paid
118	      { id: 2, amount: 400, projectId: 2, status: 'SENT' }, // 400 paid -> due 0,   paid
119	      { id: 3, amount: 150, projectId: 1, status: 'SENT' }, // nothing  -> due 150, owing
120	      { id: 4, amount: 999, projectId: 3, status: 'SENT' }, // Globex's — must not appear on Acme's
121	    ],
122	    payments: [
123	      { id: 1, invoiceId: 1, amount: 200, date: '2021-03-14' },
124	      { id: 2, invoiceId: 2, amount: 400, date: '2022-08-19' },
125	      // Globex's invoice has a payment too, to prove it is excluded figure and all.
126	      { id: 3, invoiceId: 4, amount: 50, date: '2023-05-27' },
127	    ],
128	  });
129	}
130	
131	test.describe('A client statement puts all their invoices in one place', () => {
132	  test('the statement is revealed by its open control', async ({ page }) => {
133	    await seedTwoClients();
134	
135	    await page.goto('/clients/1');
136	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
137	
138	    // Before it is opened, the statement is not shown — the open control is what reveals it.
139	    await expect(page.getByTestId('client-statement')).toHaveCount(0);
140	
141	    const opener = page.getByTestId('client-statement-open');
142	    await expect(opener).toBeVisible();
143	    await opener.click();
144	
145	    await expect(page.getByTestId('client-statement')).toBeVisible();
146	    await expect(page.getByTestId('client-statement-table')).toBeVisible();
147	  });
148	
149	  test("lists every invoice of the client, from every project, each with its figures", async ({
150	    page,
151	  }) => {
152	    await seedTwoClients();
153	    await openStatement(page, 1);
154	
155	    // Exactly Acme's three invoices — drawn from BOTH its projects — are in the one table.
156	    await expect(statementRows(page)).toHaveCount(3);
157	    await expect(page.getByTestId('statement-invoice-row-1')).toBeVisible();
158	    await expect(page.getByTestId('statement-invoice-row-2')).toBeVisible();
159	    await expect(page.getByTestId('statement-invoice-row-3')).toBeVisible();
160	
161	    // Each row names which invoice it is.
162	    await expect(cell(page, 1, 'statement-invoice-id')).toHaveText(idToken(1));
163	    await expect(cell(page, 2, 'statement-invoice-id')).toHaveText(idToken(2));
164	    await expect(cell(page, 3, 'statement-invoice-id')).toHaveText(idToken(3));
165	
166	    // invoice 1: amount 500, 200 paid, 300 still due.
167	    await expect(cell(page, 1, 'statement-invoice-amount')).toContainText(money(500));
168	    await expect(cell(page, 1, 'statement-invoice-paid')).toContainText(money(200));
169	    await expect(cell(page, 1, 'statement-invoice-due')).toContainText(money(300));
170	
171	    // invoice 2: amount 400, fully paid, nothing due.
172	    await expect(cell(page, 2, 'statement-invoice-amount')).toContainText(money(400));
173	    await expect(cell(page, 2, 'statement-invoice-paid')).toContainText(money(400));
174	    await expect(cell(page, 2, 'statement-invoice-due')).toContainText(money(0));
175	
176	    // invoice 3: amount 150, nothing paid, all of it still due.
177	    await expect(cell(page, 3, 'statement-invoice-amount')).toContainText(money(150));
178	    await expect(cell(page, 3, 'statement-invoice-paid')).toContainText(money(0));
179	    await expect(cell(page, 3, 'statement-invoice-due')).toContainText(money(150));
180	  });
181	
182	  test("another client's invoice is not on this client's statement", async ({ page }) => {
183	    await seedTwoClients();
184	    await openStatement(page, 1);
185	
186	    // Globex's invoice (id 4, amount 999) is nowhere on Acme's statement.
187	    await expect(page.getByTestId('statement-invoice-row-4')).toHaveCount(0);
188	    await expect(page.getByTestId('client-statement')).not.toContainText('999');
189	  });
190	
191	  test('each invoice shows its worked-out status: owing, part paid, or paid', async ({ page }) => {
192	    await seedTwoClients();
193	    await openStatement(page, 1);
194	
195	    await expectRowStatus(page, 1, 'part'); // 200 of 500
196	    await expectRowStatus(page, 2, 'paid'); // 400 of 400
197	    await expectRowStatus(page, 3, 'owing'); // 0 of 150
198	  });
199	
200	  test('the statement shows the total the client still owes', async ({ page }) => {
201	    await seedTwoClients();
202	    await openStatement(page, 1);
203	
204	    const total = page.getByTestId('client-outstanding-total');
205	    await expect(total).toBeVisible();
206	
207	    // What they still owe is the sum of the per-invoice dues: 300 + 0 + 150 = 450.
208	    await expect(total).toContainText(money(450));
209	
210	    // Not the gross of every amount (1050), nor the gross of the not-fully-paid invoices (650): the
211	    // partial payment on invoice 1 and the full payment on invoice 2 must both have been netted off.
212	    await expect(total).not.toContainText(money(1050));
213	    await expect(total).not.toContainText(money(650));
214	    // And Globex's invoice (999, or its 949 unpaid remainder) is no part of Acme's owed figure.
215	    await expect(total).not.toContainText(money(999));
216	    await expect(total).not.toContainText(money(949));
217	  });
218	
219	  test("a different client's statement shows only that client's own invoices and owed total", async ({
220	    page,
221	  }) => {
222	    await seedTwoClients();
223	    await openStatement(page, 2);
224	
225	    // Globex has exactly one invoice (id 4) — Acme's three are not here.
226	    await expect(statementRows(page)).toHaveCount(1);
227	    await expect(page.getByTestId('statement-invoice-row-4')).toBeVisible();
228	    await expect(page.getByTestId('statement-invoice-row-1')).toHaveCount(0);
229	
230	    // Its figures: amount 999, 50 paid, 949 still due, part paid.
231	    await expect(cell(page, 4, 'statement-invoice-amount')).toContainText(money(999));
232	    await expect(cell(page, 4, 'statement-invoice-paid')).toContainText(money(50));
233	    await expect(cell(page, 4, 'statement-invoice-due')).toContainText(money(949));
234	    await expectRowStatus(page, 4, 'part');
235	
236	    // Globex is owed only its own remainder: 949. Acme's 450 is nowhere on Globex's statement.
237	    const total = page.getByTestId('client-outstanding-total');
238	    await expect(total).toContainText(money(949));
239	    await expect(total).not.toContainText(money(450));
240	  });
241	
242	  test('a client with no invoices has an empty statement that owes nothing', async ({ page }) => {
243	    await resetAndSeed({
244	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
245	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
246	      invoices: [],
247	      payments: [],
248	    });
249	
250	    await openStatement(page, 1);
251	
252	    // Nothing invoiced, so no rows — and zero is money too: owed is shown as $0.00, not a bare 0.
253	    await expect(statementRows(page)).toHaveCount(0);
254	    await expect(page.getByTestId('client-outstanding-total')).toContainText(money(0));
255	  });
256	
257	  test('recording a payment lowers what the client owes', async ({ page }) => {
258	    // Acme with two SENT invoices: 500 (200 already paid, due 300) and 150 (nothing paid, due 150).
259	    // Owed starts at 300 + 150 = 450.
260	    await resetAndSeed({
261	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
262	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
263	      invoices: [
264	        { id: 1, amount: 500, projectId: 1, status: 'SENT' },
265	        { id: 2, amount: 150, projectId: 1, status: 'SENT' },
266	      ],
267	      payments: [{ id: 1, invoiceId: 1, amount: 200, date: '2021-03-14' }],
268	    });
269	
270	    await openStatement(page, 1);
271	    await expect(cell(page, 1, 'statement-invoice-due')).toContainText(money(300));
272	    await expect(page.getByTestId('client-outstanding-total')).toContainText(money(450));
273	
274	    // Record another 100 against invoice 1, on the invoice's own detail page.
275	    await page.goto('/invoices/1');
276	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
277	    await page.getByTestId('payment-form-amount').fill('100');
278	    await page.getByTestId('payment-form-date').fill('2023-05-27');
279	    await page.getByTestId('payment-form-submit').click();
280	    await expect(rowByAmount(page, 100)).toHaveCount(1);
281	
282	    // Back on the statement, invoice 1 now owes 200 (500 - 300 paid) and the client's owed total has
283	    // fallen by the 100 just paid: 450 -> 350. The statement is derived from server-held data, so it
284	    // reflects the new payment on a fresh open.
285	    await openStatement(page, 1);
286	    await expect(cell(page, 1, 'statement-invoice-paid')).toContainText(money(300));
287	    await expect(cell(page, 1, 'statement-invoice-due')).toContainText(money(200));
288	    await expect(cell(page, 2, 'statement-invoice-due')).toContainText(money(150)); // untouched
289	    await expect(page.getByTestId('client-outstanding-total')).toContainText(money(350));
290	    await expect(page.getByTestId('client-outstanding-total')).not.toContainText(money(450));
291	  });
292	});
